import React, { useState, useEffect } from 'react';
import { ToastContainer, toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import Calendar from 'react-calendar';
import 'react-calendar/dist/Calendar.css';

function CustomerDashboard({ user, onLogout }) {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [services, setServices] = useState([]);
  const [vehicles, setVehicles] = useState([]);
  const [bookings, setBookings] = useState([]);
  const [onlineDrivers, setOnlineDrivers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showBookingModal, setShowBookingModal] = useState(false);
  const [selectedService, setSelectedService] = useState(null);
  const [showVehicleModal, setShowVehicleModal] = useState(false);
  const [showProfileModal, setShowProfileModal] = useState(false);
  const [showSettingsModal, setShowSettingsModal] = useState(false);
  const [darkMode, setDarkMode] = useState(false);
  const [notifications, setNotifications] = useState([]);
  const [unreadCount, setUnreadCount] = useState(3);
  const [showNotifications, setShowNotifications] = useState(false);

  // User profile state
  const [profile, setProfile] = useState({
    fullName: `${user?.firstName || ''} ${user?.lastName || ''}`,
    email: user?.email || '',
    phone: user?.phone || '',
    avatar: user?.profilePicture || 'https://ui-avatars.com/api/?background=2563eb&color=fff&name=' + encodeURIComponent(user?.firstName || 'User'),
    preferredLocation: user?.address || '',
    loyaltyPoints: 1250,
    memberSince: new Date(user?.createdAt || Date.now()).toLocaleDateString()
  });

  // Settings state
  const [settings, setSettings] = useState({
    emailNotifications: true,
    pushNotifications: true,
    smsNotifications: false,
    darkMode: false,
    language: 'english',
    hideProfile: false,
    offlineMode: false
  });

  const [newVehicle, setNewVehicle] = useState({ make: '', model: '', year: '', licensePlate: '', color: '' });
  const [filters, setFilters] = useState({ category: 'all', search: '', minPrice: '', maxPrice: '' });
  const [selectedDate, setSelectedDate] = useState(new Date());

  const token = localStorage.getItem('token');

  // Sample notifications data
  const sampleNotifications = [
    { id: 1, type: 'booking_confirmed', title: 'Booking Confirmed', message: 'Your oil change has been confirmed', time: '2 hours ago', read: false, icon: '✅' },
    { id: 2, type: 'driver_assigned', title: 'Driver Assigned', message: 'Mike has been assigned to pick up your car', time: '5 hours ago', read: false, icon: '🚗' },
    { id: 3, type: 'promotion', title: 'Special Offer', message: '20% off on brake service this week!', time: '1 day ago', read: false, icon: '🎉' },
    { id: 4, type: 'service_completed', title: 'Service Completed', message: 'Your tire rotation is complete', time: '2 days ago', read: true, icon: '✅' }
  ];

  useEffect(() => {
    fetchAllData();
    setNotifications(sampleNotifications);
    const interval = setInterval(fetchOnlineDrivers, 30000);
    return () => clearInterval(interval);
  }, []);

  const fetchAllData = async () => {
    setLoading(true);
    try {
      await Promise.all([
        fetchServices(),
        fetchVehicles(),
        fetchBookings(),
        fetchOnlineDrivers()
      ]);
    } catch (error) {
      console.error('Error fetching data:', error);
      toast.error('Failed to load data');
    } finally {
      setLoading(false);
    }
  };

  const fetchServices = async () => {
    let url = 'http://localhost:5000/api/services?';
    if (filters.category && filters.category !== 'all') url += `category=${filters.category}&`;
    if (filters.search) url += `search=${filters.search}&`;
    if (filters.minPrice) url += `minPrice=${filters.minPrice}&`;
    if (filters.maxPrice) url += `maxPrice=${filters.maxPrice}&`;

    const res = await fetch(url);
    const data = await res.json();
    if (data.success) setServices(data.services);
  };

  const fetchVehicles = async () => {
    const res = await fetch('http://localhost:5000/api/services/customer/vehicles', {
      headers: { 'Authorization': `Bearer ${token}` }
    });
    const data = await res.json();
    if (data.success) setVehicles(data.vehicles);
  };

  const fetchBookings = async () => {
    const res = await fetch('http://localhost:5000/api/services/customer/bookings', {
      headers: { 'Authorization': `Bearer ${token}` }
    });
    const data = await res.json();
    if (data.success) setBookings(data.bookings);
  };

  const fetchOnlineDrivers = async () => {
    const res = await fetch('http://localhost:5000/api/driver/online');
    const data = await res.json();
    if (data.success) setOnlineDrivers(data.drivers);
  };

  const addVehicle = async (e) => {
    e.preventDefault();
    try {
      const res = await fetch('http://localhost:5000/api/services/customer/vehicles', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify(newVehicle)
      });
      const data = await res.json();
      if (data.success) {
        toast.success('Vehicle added successfully!');
        setShowVehicleModal(false);
        setNewVehicle({ make: '', model: '', year: '', licensePlate: '', color: '' });
        fetchVehicles();
      }
    } catch (error) {
      toast.error('Failed to add vehicle');
    }
  };

  const updateProfile = async (e) => {
    e.preventDefault();
    try {
      // In production, call API to update profile
      toast.success('Profile updated successfully!');
      setShowProfileModal(false);
    } catch (error) {
      toast.error('Failed to update profile');
    }
  };

  const updateSettings = async (e) => {
    e.preventDefault();
    try {
      setDarkMode(settings.darkMode);
      toast.success('Settings saved!');
      setShowSettingsModal(false);
    } catch (error) {
      toast.error('Failed to save settings');
    }
  };

  const markNotificationRead = (id) => {
    setNotifications(notifications.map(n => 
      n.id === id ? { ...n, read: true } : n
    ));
    setUnreadCount(notifications.filter(n => !n.read && n.id !== id).length);
  };

  const markAllRead = () => {
    setNotifications(notifications.map(n => ({ ...n, read: true })));
    setUnreadCount(0);
  };

  const getStatusBadge = (status) => {
    const colors = {
      pending: '#f59e0b',
      confirmed: '#10b981',
      'in-progress': '#3b82f6',
      completed: '#8b5cf6',
      cancelled: '#ef4444'
    };
    return { backgroundColor: colors[status] || '#6b7280', color: 'white', padding: '4px 12px', borderRadius: '20px', fontSize: '12px', display: 'inline-block' };
  };

  const getNotificationIcon = (type) => {
    const icons = {
      booking_confirmed: '✅',
      driver_assigned: '🚗',
      service_started: '🔧',
      service_completed: '🎉',
      promotion: '🎁',
      payment_receipt: '💰'
    };
    return icons[type] || '📢';
  };

  const totalSpent = bookings.filter(b => b.status === 'completed').reduce((sum, b) => sum + (b.totalAmount || 0), 0);
  const upcomingBookings = bookings.filter(b => b.status !== 'completed' && b.status !== 'cancelled');
  const completedBookings = bookings.filter(b => b.status === 'completed');

  // Calculate next service reminder (mock)
  const nextServiceReminder = vehicles.length > 0 ? `${vehicles[0]?.make} ${vehicles[0]?.model} needs oil change in 500 miles` : 'Add a vehicle to get reminders';

  return (
    <div style={{ ...styles.dashboard, backgroundColor: darkMode ? '#1a1a2e' : '#f3f4f6' }}>
      <ToastContainer position="top-right" />

      {/* Header */}
      <div style={{ ...styles.header, backgroundColor: darkMode ? '#16213e' : '#1f2937' }}>
        <div style={styles.logoSection}>
          <span style={styles.logoIcon}>🚗💨</span>
          <h1 style={styles.logoText}>Car Care Connect</h1>
        </div>

        <div style={styles.headerRight}>
          {/* Notification Bell */}
          <div style={styles.notificationIcon} onClick={() => setShowNotifications(!showNotifications)}>
            🔔
            {unreadCount > 0 && <span style={styles.notificationBadge}>{unreadCount}</span>}
          </div>

          {/* Dark Mode Toggle */}
          <button style={styles.themeToggle} onClick={() => { setDarkMode(!darkMode); setSettings({...settings, darkMode: !darkMode}); }}>
            {darkMode ? '☀️' : '🌙'}
          </button>

          <div style={styles.userInfo}>
            <img src={profile.avatar} alt="avatar" style={styles.avatar} />
            <span>{user?.firstName} {user?.lastName}</span>
            <button onClick={onLogout} style={styles.logoutButton}>Logout</button>
          </div>
        </div>
      </div>

      {/* Notification Dropdown */}
      {showNotifications && (
        <div style={{ ...styles.notificationDropdown, backgroundColor: darkMode ? '#1e293b' : 'white' }}>
          <div style={styles.notificationHeader}>
            <h3>Notifications</h3>
            <button onClick={markAllRead} style={styles.markAllRead}>Mark all as read</button>
          </div>
          {notifications.map(notif => (
            <div key={notif.id} style={{ ...styles.notificationItem, opacity: notif.read ? 0.6 : 1, backgroundColor: notif.read ? 'transparent' : (darkMode ? '#334155' : '#f0f9ff') }} onClick={() => markNotificationRead(notif.id)}>
              <span style={styles.notificationIconSmall}>{notif.icon}</span>
              <div style={styles.notificationContent}>
                <div style={styles.notificationTitle}>{notif.title}</div>
                <div style={styles.notificationMessage}>{notif.message}</div>
                <div style={styles.notificationTime}>{notif.time}</div>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Stats Cards */}
      <div style={styles.statsGrid}>
        <div style={{ ...styles.statCard, backgroundColor: darkMode ? '#1e293b' : 'white' }}>
          <h3>🚗 Vehicles</h3>
          <p style={styles.statNumber}>{vehicles.length}</p>
          <button style={styles.smallBtn} onClick={() => setShowVehicleModal(true)}>+ Add</button>
        </div>
        <div style={{ ...styles.statCard, backgroundColor: darkMode ? '#1e293b' : 'white' }}>
          <h3>📅 Bookings</h3>
          <p style={styles.statNumber}>{bookings.length}</p>
        </div>
        <div style={{ ...styles.statCard, backgroundColor: darkMode ? '#1e293b' : 'white' }}>
          <h3>💰 Spent</h3>
          <p style={styles.statNumber}>${totalSpent.toLocaleString()}</p>
        </div>
        <div style={{ ...styles.statCard, backgroundColor: darkMode ? '#1e293b' : 'white' }}>
          <h3>⭐ Loyalty</h3>
          <p style={styles.statNumber}>{profile.loyaltyPoints} pts</p>
        </div>
      </div>

      {/* Quick Actions FAB */}
      <button style={styles.fab} onClick={() => setActiveTab('services')}>
        + Quick Book
      </button>

      {/* Tabs */}
      <div style={{ ...styles.tabs, backgroundColor: darkMode ? '#1e293b' : 'white' }}>
        <button style={{...styles.tab, ...(activeTab === 'dashboard' ? styles.activeTab : {})}} onClick={() => setActiveTab('dashboard')}>📊 Dashboard</button>
        <button style={{...styles.tab, ...(activeTab === 'services' ? styles.activeTab : {})}} onClick={() => { fetchServices(); setActiveTab('services'); }}>🔧 Services</button>
        <button style={{...styles.tab, ...(activeTab === 'vehicles' ? styles.activeTab : {})}} onClick={() => setActiveTab('vehicles')}>🚗 Vehicles</button>
        <button style={{...styles.tab, ...(activeTab === 'bookings' ? styles.activeTab : {})}} onClick={() => setActiveTab('bookings')}>📅 Bookings</button>
        <button style={{...styles.tab, ...(activeTab === 'profile' ? styles.activeTab : {})}} onClick={() => setActiveTab('profile')}>👤 Profile</button>
        <button style={{...styles.tab, ...(activeTab === 'settings' ? styles.activeTab : {})}} onClick={() => setActiveTab('settings')}>⚙️ Settings</button>
      </div>

      {/* Content */}
      <div style={styles.content}>
        {loading ? <div style={styles.loading}>Loading...</div> : (
          <>
            {/* Dashboard Tab */}
            {activeTab === 'dashboard' && (
              <div>
                {/* Welcome Banner */}
                <div style={{ ...styles.welcomeCard, backgroundColor: darkMode ? '#1e293b' : '#2563eb' }}>
                  <div>
                    <h2>Welcome back, {user?.firstName}! 👋</h2>
                    <p>Your next service is just a click away</p>
                  </div>
                  <span style={styles.loyaltyBadge}>⭐ {profile.loyaltyPoints} points</span>
                </div>

                {/* Two Column Layout */}
                <div style={styles.twoColumn}>
                  {/* Left Column */}
                  <div>
                    {/* Upcoming Appointments */}
                    <div style={{ ...styles.card, backgroundColor: darkMode ? '#1e293b' : 'white' }}>
                      <h3>📅 Upcoming Appointments</h3>
                      {upcomingBookings.length === 0 ? (
                        <p>No upcoming appointments</p>
                      ) : (
                        upcomingBookings.map(booking => (
                          <div key={booking._id} style={styles.appointmentItem}>
                            <div><strong>{booking.serviceName}</strong></div>
                            <div>{new Date(booking.bookingDate).toLocaleDateString()} at {booking.bookingTime}</div>
                            <span style={getStatusBadge(booking.status)}>{booking.status}</span>
                          </div>
                        ))
                      )}
                    </div>

                    {/* Vehicle Health Reminders */}
                    <div style={{ ...styles.card, backgroundColor: darkMode ? '#1e293b' : 'white' }}>
                      <h3>🔧 Vehicle Health Reminders</h3>
                      <div style={styles.reminderItem}>
                        <span>⚠️</span>
                        <span>{nextServiceReminder}</span>
                      </div>
                      {vehicles.map(vehicle => (
                        <div key={vehicle._id} style={styles.reminderItem}>
                          <span>🔍</span>
                          <span>{vehicle.year} {vehicle.make} {vehicle.model} - Next service in 30 days</span>
                        </div>
                      ))}
                    </div>

                    {/* Favorite Providers */}
                    <div style={{ ...styles.card, backgroundColor: darkMode ? '#1e293b' : 'white' }}>
                      <h3>⭐ Favorite Providers</h3>
                      <p>No favorite providers yet. Book services to add favorites!</p>
                    </div>
                  </div>

                  {/* Right Column */}
                  <div>
                    {/* Calendar */}
                    <div style={{ ...styles.card, backgroundColor: darkMode ? '#1e293b' : 'white' }}>
                      <h3>📆 Calendar</h3>
                      <Calendar onChange={setSelectedDate} value={selectedDate} />
                    </div>

                    {/* Recent Activity */}
                    <div style={{ ...styles.card, backgroundColor: darkMode ? '#1e293b' : 'white' }}>
                      <h3>🕐 Recent Activity</h3>
                      {bookings.slice(0, 5).map(booking => (
                        <div key={booking._id} style={styles.activityItem}>
                          <span>{booking.status === 'completed' ? '✅' : '🔄'}</span>
                          <span>{booking.serviceName}</span>
                          <span style={styles.activityTime}>{new Date(booking.createdAt).toLocaleDateString()}</span>
                        </div>
                      ))}
                    </div>

                    {/* Spending Summary */}
                    <div style={{ ...styles.card, backgroundColor: darkMode ? '#1e293b' : 'white' }}>
                      <h3>💰 Spending Summary</h3>
                      <div style={styles.spendingItem}>
                        <span>Total Spent:</span>
                        <strong>${totalSpent.toLocaleString()}</strong>
                      </div>
                      <div style={styles.spendingItem}>
                        <span>Average per booking:</span>
                        <strong>${completedBookings.length > 0 ? (totalSpent / completedBookings.length).toFixed(2) : 0}</strong>
                      </div>
                      <div style={styles.spendingItem}>
                        <span>Total bookings:</span>
                        <strong>{bookings.length}</strong>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            )}

            {/* Services Tab */}
            {activeTab === 'services' && (
              <div>
                <div style={styles.filtersBar}>
                  <select style={styles.filterSelect} value={filters.category} onChange={(e) => setFilters({...filters, category: e.target.value})}>
                    <option value="all">All Categories</option>
                    <option value="oil-change">Oil Change</option>
                    <option value="brake-repair">Brake Repair</option>
                    <option value="tire-service">Tire Service</option>
                    <option value="engine-repair">Engine Repair</option>
                  </select>
                  <input style={styles.filterInput} type="text" placeholder="Search services..." value={filters.search} onChange={(e) => setFilters({...filters, search: e.target.value})} />
                  <input style={styles.filterInputSmall} type="number" placeholder="Min $" value={filters.minPrice} onChange={(e) => setFilters({...filters, minPrice: e.target.value})} />
                  <input style={styles.filterInputSmall} type="number" placeholder="Max $" value={filters.maxPrice} onChange={(e) => setFilters({...filters, maxPrice: e.target.value})} />
                  <button style={styles.filterBtn} onClick={fetchServices}>Apply</button>
                </div>

                <div style={styles.servicesGrid}>
                  {services.map(service => (
                    <div key={service._id} style={{ ...styles.serviceCard, backgroundColor: darkMode ? '#1e293b' : 'white' }}>
                      <h3>{service.name}</h3>
                      <p style={styles.providerName}>🔧 {service.providerBusinessName || service.providerName}</p>
                      <p>{service.description?.substring(0, 100)}...</p>
                      <div style={styles.servicePrice}>
                        <span style={styles.price}>${service.price}</span>
                        <span style={styles.duration}>⏱️ {service.duration} min</span>
                      </div>
                      <button style={styles.bookBtn} onClick={() => { setSelectedService(service); setShowBookingModal(true); }}>Book Now →</button>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Vehicles Tab */}
            {activeTab === 'vehicles' && (
              <div>
                <button style={styles.addVehicleBtn} onClick={() => setShowVehicleModal(true)}>+ Add Vehicle</button>
                {vehicles.length === 0 ? (
                  <div style={{ ...styles.emptyState, backgroundColor: darkMode ? '#1e293b' : 'white' }}>No vehicles added. Add your first vehicle!</div>
                ) : (
                  vehicles.map(vehicle => (
                    <div key={vehicle._id} style={{ ...styles.vehicleCard, backgroundColor: darkMode ? '#1e293b' : 'white' }}>
                      <div><strong>{vehicle.year} {vehicle.make} {vehicle.model}</strong></div>
                      <div>License: {vehicle.licensePlate} | Color: {vehicle.color || 'N/A'}</div>
                    </div>
                  ))
                )}
              </div>
            )}

            {/* Bookings Tab */}
            {activeTab === 'bookings' && (
              <div>
                {bookings.length === 0 ? (
                  <div style={{ ...styles.emptyState, backgroundColor: darkMode ? '#1e293b' : 'white' }}>No bookings yet. Book your first service!</div>
                ) : (
                  bookings.map(booking => (
                    <div key={booking._id} style={{ ...styles.bookingCard, backgroundColor: darkMode ? '#1e293b' : 'white' }}>
                      <div style={styles.bookingHeader}>
                        <div>
                          <h3>{booking.serviceName}</h3>
                          <p>Provider: {booking.providerId?.businessName || booking.providerId?.firstName}</p>
                        </div>
                        <span style={getStatusBadge(booking.status)}>{booking.status}</span>
                      </div>
                      <div style={styles.bookingDetails}>
                        <span>📅 {new Date(booking.bookingDate).toLocaleDateString()}</span>
                        <span>⏰ {booking.bookingTime}</span>
                        <span>💰 ${booking.totalAmount}</span>
                      </div>
                      {booking.driverId && (
                        <div style={styles.driverInfo}>
                          <span>🚗 Driver: {booking.driverId?.firstName} {booking.driverId?.lastName}</span>
                        </div>
                      )}
                    </div>
                  ))
                )}
              </div>
            )}

            {/* Profile Tab */}
            {activeTab === 'profile' && (
              <div style={{ ...styles.profileContainer, backgroundColor: darkMode ? '#1e293b' : 'white' }}>
                <div style={styles.profileHeader}>
                  <img src={profile.avatar} alt="avatar" style={styles.profileAvatar} />
                  <div>
                    <h2>{profile.fullName}</h2>
                    <p>Member since {profile.memberSince}</p>
                    <button style={styles.editProfileBtn} onClick={() => setShowProfileModal(true)}>✏️ Edit Profile</button>
                  </div>
                </div>
                <div style={styles.profileInfo}>
                  <div><strong>📧 Email:</strong> {profile.email}</div>
                  <div><strong>📞 Phone:</strong> {profile.phone}</div>
                  <div><strong>📍 Location:</strong> {profile.preferredLocation || 'Not set'}</div>
                  <div><strong>⭐ Loyalty Points:</strong> {profile.loyaltyPoints}</div>
                  <div><strong>🚗 Vehicles:</strong> {vehicles.length}</div>
                  <div><strong>📅 Total Bookings:</strong> {bookings.length}</div>
                </div>
              </div>
            )}

            {/* Settings Tab */}
            {activeTab === 'settings' && (
              <div style={{ ...styles.settingsContainer, backgroundColor: darkMode ? '#1e293b' : 'white' }}>
                <h2>⚙️ Settings</h2>

                <div style={styles.settingsSection}>
                  <h3>🔔 Notification Preferences</h3>
                  <label style={styles.settingItem}>
                    <input type="checkbox" checked={settings.emailNotifications} onChange={(e) => setSettings({...settings, emailNotifications: e.target.checked})} />
                    Email Notifications
                  </label>
                  <label style={styles.settingItem}>
                    <input type="checkbox" checked={settings.pushNotifications} onChange={(e) => setSettings({...settings, pushNotifications: e.target.checked})} />
                    Push Notifications
                  </label>
                  <label style={styles.settingItem}>
                    <input type="checkbox" checked={settings.smsNotifications} onChange={(e) => setSettings({...settings, smsNotifications: e.target.checked})} />
                    SMS Notifications
                  </label>
                </div>

                <div style={styles.settingsSection}>
                  <h3>🌐 Language & Region</h3>
                  <select style={styles.settingsSelect} value={settings.language} onChange={(e) => setSettings({...settings, language: e.target.value})}>
                    <option value="english">English</option>
                    <option value="spanish">Spanish</option>
                    <option value="french">French</option>
                  </select>
                </div>

                <div style={styles.settingsSection}>
                  <h3>🔒 Privacy</h3>
                  <label style={styles.settingItem}>
                    <input type="checkbox" checked={settings.hideProfile} onChange={(e) => setSettings({...settings, hideProfile: e.target.checked})} />
                    Hide my profile from others
                  </label>
                  <label style={styles.settingItem}>
                    <input type="checkbox" checked={settings.offlineMode} onChange={(e) => setSettings({...settings, offlineMode: e.target.checked})} />
                    Offline Mode (hide online status)
                  </label>
                </div>

                <button style={styles.saveSettingsBtn} onClick={() => setShowSettingsModal(true)}>Save Settings</button>
              </div>
            )}
          </>
        )}
      </div>

      {/* Profile Edit Modal */}
      {showProfileModal && (
        <div style={styles.modal}>
          <div style={{ ...styles.modalContent, backgroundColor: darkMode ? '#1e293b' : 'white' }}>
            <h2>Edit Profile</h2>
            <form onSubmit={updateProfile}>
              <input style={styles.input} type="text" placeholder="Full Name" value={profile.fullName} onChange={(e) => setProfile({...profile, fullName: e.target.value})} required />
              <input style={styles.input} type="email" placeholder="Email" value={profile.email} onChange={(e) => setProfile({...profile, email: e.target.value})} required />
              <input style={styles.input} type="tel" placeholder="Phone" value={profile.phone} onChange={(e) => setProfile({...profile, phone: e.target.value})} required />
              <input style={styles.input} type="text" placeholder="Preferred Location" value={profile.preferredLocation} onChange={(e) => setProfile({...profile, preferredLocation: e.target.value})} />
              <div style={styles.modalActions}>
                <button type="submit" style={styles.submitBtn}>Save Changes</button>
                <button type="button" style={styles.cancelBtn} onClick={() => setShowProfileModal(false)}>Cancel</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Settings Modal */}
      {showSettingsModal && (
        <div style={styles.modal}>
          <div style={{ ...styles.modalContent, backgroundColor: darkMode ? '#1e293b' : 'white' }}>
            <h2>Save Settings</h2>
            <p>Your settings have been updated. Click Save to apply changes.</p>
            <div style={styles.modalActions}>
              <button style={styles.submitBtn} onClick={updateSettings}>Save Settings</button>
              <button style={styles.cancelBtn} onClick={() => setShowSettingsModal(false)}>Cancel</button>
            </div>
          </div>
        </div>
      )}

      {/* Vehicle Modal */}
      {showVehicleModal && (
        <div style={styles.modal}>
          <div style={{ ...styles.modalContentSmall, backgroundColor: darkMode ? '#1e293b' : 'white' }}>
            <h2>Add Vehicle</h2>
            <form onSubmit={addVehicle}>
              <input style={styles.input} placeholder="Make" value={newVehicle.make} onChange={(e) => setNewVehicle({...newVehicle, make: e.target.value})} required />
              <input style={styles.input} placeholder="Model" value={newVehicle.model} onChange={(e) => setNewVehicle({...newVehicle, model: e.target.value})} required />
              <input style={styles.input} type="number" placeholder="Year" value={newVehicle.year} onChange={(e) => setNewVehicle({...newVehicle, year: e.target.value})} required />
              <input style={styles.input} placeholder="License Plate" value={newVehicle.licensePlate} onChange={(e) => setNewVehicle({...newVehicle, licensePlate: e.target.value})} required />
              <input style={styles.input} placeholder="Color" value={newVehicle.color} onChange={(e) => setNewVehicle({...newVehicle, color: e.target.value})} />
              <div style={styles.modalActions}>
                <button type="submit" style={styles.submitBtn}>Save Vehicle</button>
                <button type="button" style={styles.cancelBtn} onClick={() => setShowVehicleModal(false)}>Cancel</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

